-- ── Operator and test accounts ─────────────────────────────────────────────
--
-- Added after the pg_dump extract because these two are *authored*, not captured.
--
-- `platform-admin@tradingroom.test` is the account to sign in with locally. The `.test` suffix is
-- reserved for fixtures and cannot identify or route to a real mailbox. There is no signup endpoint - by
-- design, this is an invite-based product - so the first account has to be provisioned out of
-- band. The hash below was produced by `cargo run -p tradingroom-api --example hash_password`, which is
-- the same code path `auth::login` verifies against, so it cannot drift from the parameters the
-- service actually uses.
--
-- The password is a known development credential and is written here on purpose: this file
-- seeds a local fixture database, and a secret nobody can look up is a secret somebody will
-- replace with `password`. It must never be used anywhere reachable.
--
-- `target@acme.test` exists only so the moderation tests have somebody to mute. Muting a member
-- that other tests are posting as makes both flaky - which is exactly what happened before this
-- row existed.

INSERT INTO public.users
  (id, email, email_hash, password_hash, display_name, is_platform_admin, preferences, is_guest)
VALUES
  ('a0000001-0000-4000-8000-0000000000ad',
   'platform-admin@tradingroom.test',
   'ff485f315dcb7d0dbf57ad7114f26e48',
   '$argon2id$v=19$m=19456,t=2,p=1$7lGvtllJu3APHvuRgdB58Q$5TcB3QRyLlKpDPWTeS2VPjbiuaaqp5x6e0BOg+p3Ab8',
   'Test Platform Admin',
   true,
   '{}'::jsonb,
   false),
  ('a0000001-0000-4000-8000-000000000005',
   'target@acme.test',
   'c33970a933241248f11a2b2ed41e5cbb',
   NULL,
   'Tessa Target',
   false,
   '{}'::jsonb,
   false)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.room_members
  (id, enterprise_id, room_id, user_id, role, display_name)
VALUES
  ('a0000002-0000-4000-8000-0000000000ad',
   'a0000000-0000-4000-8000-000000000001',
   'a0000003-0000-4000-8000-000000000001',
   'a0000001-0000-4000-8000-0000000000ad',
   'owner',
   'Test Platform Admin'),
  ('a0000002-0000-4000-8000-000000000005',
   'a0000000-0000-4000-8000-000000000001',
   'a0000003-0000-4000-8000-000000000001',
   'a0000001-0000-4000-8000-000000000005',
   'member',
   'Tessa Target')
ON CONFLICT (id) DO NOTHING;

-- The assumption the ordering above depends on.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.users
    WHERE email_hash <> md5(lower(email::text))
  ) THEN
    RAISE EXCEPTION 'a seeded email_hash does not match the normalized fixture email';
  END IF;

  IF EXISTS (SELECT 1 FROM public.users WHERE guest_created_in_room_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a seeded user references a room; users can no longer be loaded before rooms';
  END IF;
END
$$;

COMMIT;
